// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Phishable} from "../src/Phishable.sol";

contract InvMutTest is Test {
    Phishable c;
    function setUp() public { c = new Phishable(address(this)); }

    function testFuzz_property(uint256 depositAmount, address recipient) public {
        depositAmount = bound(depositAmount, 1, 1 ether);
        vm.assume(recipient != address(0));

        vm.deal(address(this), depositAmount);
        (bool sent, ) = address(c).call{value: depositAmount}("\x00");
        require(sent);

        uint256 beforeRecipient = recipient.balance;
        uint256 beforeC = address(c).balance;
        require(beforeC == depositAmount);

        c.withdrawAll(recipient);

        assertTrue(address(c).balance == 0 && recipient.balance == beforeRecipient + beforeC);
    }
}
